# Attack: small e=3, unpadded RSA
import gmpy2

c = 343478107279667757  # given ciphertext
# Since m^3 < n, c = m^3 exactly (no modular reduction)
m, exact = gmpy2.iroot(c, 3)
if exact:
    print(m.to_bytes((m.bit_length() + 7) // 8, 'big').decode())

# Python stdlib alternative (no gmpy2)
# Binary search for exact cube root
def icbrt(n):
    if n < 0:
        return -icbrt(-n)
    x = int(round(n ** (1/3)))
    while x**3 > n:
        x -= 1
    while (x+1)**3 <= n:
        x += 1
    return x if x**3 == n else None

m = icbrt(c)
if m:
    print(m.to_bytes((m.bit_length()+7)//8,'big'))
